        if roots <= 0:
            self.report({"ERROR"}, "No .p3d collections found in the scene")
            return {"CANCELLED"}
        if changed <= 0:
            self.report({"WARNING"}, "No Visuals collections found inside .p3d roots")
            return {"CANCELLED"}
        self.report({"INFO"}, f"Visual 0 only: updated {changed} item(s) in {roots} .p3d root(s)")
        return {"FINISHED"}


