class CRAY_OT_IE_AddByName(Operator):
    bl_idname = "cray.ie_add_by_name"
    bl_label = "Add By Name"
    bl_description = "Find a .p3d in NH_Objects by model name and add it to the import list"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        st = context.scene.cray_ie_settings

        model_name = (getattr(st, "quick_add_p3d_name", "") or "").strip()
        model_key = _normalize_p3d_lookup_key(model_name)
        if not model_key:
            self.report({"ERROR"}, "Type a .p3d name like darkvalley_brick_farm_a")
            return {"CANCELLED"}

        search_root = bpy.path.abspath(getattr(st, "quick_add_search_root", "") or "")
        search_root = os.path.abspath(search_root) if search_root else ""
        if not search_root or not os.path.isdir(search_root):
            self.report({"ERROR"}, "NH_Objects root folder was not found")
            return {"CANCELLED"}

        existing_root = _find_existing_scene_p3d_root(context.scene, model_key)
        if existing_root is not None:
            self.report({"WARNING"}, f"{existing_root.name} is already imported in the scene")
            return {"CANCELLED"}

        matches = _find_p3d_paths_by_name(search_root, model_key)
        if not matches:
            self.report({"ERROR"}, f"{_display_p3d_name(model_key)} was not found in {search_root}")
            return {"CANCELLED"}

        chosen = matches[0]
        added = _planner_add_import_file(st, chosen)
        st.quick_add_p3d_name = model_key

        if not added:
            self.report({"WARNING"}, f"{os.path.basename(chosen)} is already in the import list")
            return {"CANCELLED"}

        if len(matches) > 1:
            print("=== Batch Import: multiple .p3d matches found ===")
            print(f"Requested: {model_key}")
            for path in matches:
                print(path)
            self.report(
                {"WARNING"},
                (
                    f"Added {os.path.basename(chosen)}; found {len(matches)} matches, "
                    f"used the first one (see System Console)"
                ),
            )
            return {"FINISHED"}

        self.report({"INFO"}, f"Added {os.path.basename(chosen)} to the import list")
        return {"FINISHED"}

class CRAY_OT_IE_RemoveFile(Operator):
    bl_idname = "cray.ie_remove_file"
    bl_label = "Remove"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        st = context.scene.cray_ie_settings
        i = st.import_active_index
        if i < 0 or i >= len(st.import_files):
            self.report({"WARNING"}, "Nothing to remove")
            return {"CANCELLED"}
        st.import_files.remove(i)
        st.import_active_index = max(0, min(i, len(st.import_files) - 1))
        return {"FINISHED"}

class CRAY_OT_IE_ClearFiles(Operator):
    bl_idname = "cray.ie_clear_files"
    bl_label = "Clear"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        st = context.scene.cray_ie_settings
        n = len(st.import_files)
        st.import_files.clear()
        st.import_active_index = 0
        self.report({"INFO"}, f"Cleared {n} file(s)")
        return {"FINISHED"}

def _planner_path_for_collection_name(collection, import_basename_map):
    if collection is None or not import_basename_map:
        return ""
    key = _display_p3d_name(_normalize_p3d_lookup_key(getattr(collection, "name", "") or "")).lower()
    return import_basename_map.get(key, "")

def _set_ie_source_path_tag_recursive(root_collection, source_path: str):
    if root_collection is None or not source_path:
        return
    for collection in _iter_collection_tree(root_collection):
        try:
            if collection == root_collection or _IE_SOURCE_PATH_KEY in collection:
                _set_ie_source_path_tag(collection, source_path)
        except Exception:
            pass
    for obj in _collect_collection_objects_recursive(root_collection):
        try:
            if _IE_SOURCE_PATH_KEY in obj:
                _set_ie_source_path_tag(obj, source_path)
        except Exception:
            pass

def _refresh_ie_scene_source_tags_from_collection_names(context, settings):
    import_basename_map = _build_ie_import_basename_map(settings)
    retagged = 0
    for root in _iter_p3d_root_collections(getattr(context, "scene", None)):
        wanted_path = _planner_path_for_collection_name(root, import_basename_map)
        if not wanted_path:
            continue
        current_path = _resolve_collection_source_path(root)
        if _norm_path(current_path) == _norm_path(wanted_path):
            continue
        _set_ie_source_path_tag_recursive(root, wanted_path)
        retagged += 1
    return retagged

def _current_scene_p3d_planner_keys(context, settings):
    import_basename_map = _build_ie_import_basename_map(settings)
    scene_paths = set()
    scene_names = set()
    roots = list(_iter_p3d_root_collections(getattr(context, "scene", None)))
    for root in roots:
        name_key = _normalize_p3d_lookup_key(getattr(root, "name", "") or "")
        if name_key:
            scene_names.add(name_key)
        source_path = _resolve_collection_source_path(root, import_basename_map)
        source_path = _norm_path(bpy.path.abspath(source_path)) if source_path else ""
        if source_path:
            scene_paths.add(source_path)
            source_key = _normalize_p3d_lookup_key(source_path)
            if source_key:
                scene_names.add(source_key)
    return roots, scene_paths, scene_names

def _ie_add_unique_p3d_root(roots, seen, context, collection):
    root = _find_p3d_root_collection_for_collection(context, collection, require_p3d=True)
    if root is None:
        return False
    return _model_split_add_unique_collection(roots, seen, root)

def _ie_selected_p3d_root_collections(context):
    roots = []
    seen = set()

    for item in getattr(context, "selected_ids", []) or []:
        if isinstance(item, bpy.types.Collection):
            _ie_add_unique_p3d_root(roots, seen, context, item)

    for obj in list(getattr(context, "selected_objects", []) or []):
        root = _find_p3d_root_collection_for_object(context, obj)
        if root is not None:
            _model_split_add_unique_collection(roots, seen, root)

    active_obj = getattr(getattr(context, "view_layer", None), "objects", None)
    active_obj = getattr(active_obj, "active", None) if active_obj is not None else None
    if active_obj is not None:
        root = _find_p3d_root_collection_for_object(context, active_obj)
        if root is not None:
            _model_split_add_unique_collection(roots, seen, root)

    active_layer = getattr(getattr(context, "view_layer", None), "active_layer_collection", None)
    active_collection = getattr(active_layer, "collection", None) if active_layer is not None else None
    if active_collection is not None:
        _ie_add_unique_p3d_root(roots, seen, context, active_collection)

    context_collection = getattr(context, "collection", None)
    if context_collection is not None:
        _ie_add_unique_p3d_root(roots, seen, context, context_collection)

    roots.sort(key=_model_split_merge_collection_sort_key)
    return roots

def _ie_resolve_export_path_for_collection(context, settings, collection):
    name_key = _normalize_p3d_lookup_key(getattr(collection, "name", "") or "")
    filename = _display_p3d_name(name_key)
    if not filename:
        return "", "collection name is not a .p3d name"

    import_basename_map = _build_ie_import_basename_map(settings)
    mapped = _planner_path_for_collection_name(collection, import_basename_map)
    if mapped:
        return mapped, ""

    search_root = bpy.path.abspath(getattr(settings, "quick_add_search_root", "") or "")
    matches = _find_p3d_paths_by_name(search_root, name_key) if search_root else []
    if matches:
        return matches[0], ""

    current_source = _resolve_collection_source_path(collection)
    current_source = _norm_path(bpy.path.abspath(current_source)) if current_source else ""
    if current_source:
        source_dir = os.path.dirname(current_source)
        if source_dir:
            return _norm_path(os.path.join(source_dir, filename)), ""

    if getattr(settings, "export_mode", "") == "CUSTOM_DIR":
        export_dir = bpy.path.abspath(getattr(settings, "export_directory", "") or "")
        if export_dir:
            return _norm_path(os.path.join(export_dir, filename)), ""

    return "", "no source path found; import once, use + to select a .p3d file, or set Custom folder"

def _ie_sync_p3d_root_collection_to_planner(context, settings, root):
    path, reason = _ie_resolve_export_path_for_collection(context, settings, root)
    if not path:
        return False, False, reason

    previous = _resolve_collection_source_path(root)
    _set_ie_source_path_tag_recursive(root, path)
    added = _planner_add_import_file(settings, path)
    retargeted = _norm_path(previous) != _norm_path(path)
    return added, retargeted, ""

class CRAY_OT_IE_AddSelectedCollections(Operator):
    bl_idname = "cray.ie_add_selected_collections"
    bl_label = "Add Selected Collection"
    bl_description = "Add selected .p3d root collection(s) to the planner and retarget Back to source by collection name"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        st = context.scene.cray_ie_settings
        roots = _ie_selected_p3d_root_collections(context)
        if not roots:
            self.report({"ERROR"}, "Select a .p3d root collection in Outliner or an object inside it")
            return {"CANCELLED"}

        added = 0
        retargeted = 0
        failed = []
        for root in roots:
            was_added, was_retargeted, reason = _ie_sync_p3d_root_collection_to_planner(context, st, root)
            if reason:
                failed.append(f"{getattr(root, 'name', '<collection>')} -> {reason}")
                continue
            if was_added:
                added += 1
            if was_retargeted:
                retargeted += 1

        if failed:
            print("=== Import/Export planner: Add Selected Collection failures ===")
            for item in failed:
                print(item)

        if added or retargeted:
            msg = f"Added {added}, retargeted {retargeted} selected .p3d collection(s)"
            if failed:
                self.report({"WARNING"}, msg + f", failed {len(failed)} (see System Console)")
            else:
                self.report({"INFO"}, msg)
            return {"FINISHED"}

        if failed:
            self.report({"ERROR"}, f"Failed to add selected collection(s), see System Console")
            return {"CANCELLED"}

        self.report({"INFO"}, "Selected collection(s) already in planner")
        return {"FINISHED"}

class CRAY_OT_IE_RefreshFiles(Operator):
    bl_idname = "cray.ie_refresh_files"
    bl_label = "Refresh"
    bl_description = (
        "Remove planner entries whose .p3d root collection is no longer in the scene "
        "and retarget renamed .p3d collections by name"
    )
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        st = context.scene.cray_ie_settings
        roots = list(_iter_p3d_root_collections(getattr(context, "scene", None)))
        if not roots:
            self.report({"WARNING"}, "No .p3d root collections in the scene; planner list unchanged")
            return {"CANCELLED"}

        roots.sort(key=_model_split_merge_collection_sort_key)
        added = 0
        retargeted = 0
        failed = []
        for root in roots:
            was_added, was_retargeted, reason = _ie_sync_p3d_root_collection_to_planner(context, st, root)
            if reason:
                failed.append(f"{getattr(root, 'name', '<collection>')} -> {reason}")
                continue
            if was_added:
                added += 1
            if was_retargeted:
                retargeted += 1

        _refresh_ie_scene_source_tags_from_collection_names(context, st)
        roots, scene_paths, scene_names = _current_scene_p3d_planner_keys(context, st)

        removed = 0
        for idx in range(len(st.import_files) - 1, -1, -1):
            item = st.import_files[idx]
            fp = _norm_path(bpy.path.abspath(item.path)) if item.path else ""
            name_key = _normalize_p3d_lookup_key(fp)
            if fp in scene_paths or name_key in scene_names:
                continue
            st.import_files.remove(idx)
            removed += 1

        st.import_active_index = max(0, min(int(getattr(st, "import_active_index", 0) or 0), len(st.import_files) - 1))
        if failed:
            print("=== Import/Export planner: Refresh skipped collections ===")
            for item in failed:
                print(item)
        msg = f"Refreshed planner: added {added}, removed {removed}, retargeted {retargeted}"
        if failed:
            self.report({"WARNING"}, msg + f", skipped {len(failed)} (see System Console)")
        else:
            self.report({"INFO"}, msg)
        return {"FINISHED"}

class CRAY_OT_IE_ImportBatch(Operator):
    bl_idname = "cray.ie_import_batch"
    bl_label = "Batch Import (A3OB)"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        st = context.scene.cray_ie_settings
        if len(st.import_files) == 0:
            self.report({"ERROR"}, "Import list is empty")
            return {"CANCELLED"}
        if not _has_any_a3ob_import_ops():
            self.report({"ERROR"}, "Arma 3 Object Builder import operators not found")
            return {"CANCELLED"}

        imported = 0
        skipped_existing = []
        failed = []
        used_op = None

        for it in st.import_files:
            fp = bpy.path.abspath(it.path)
            existing_root = _find_existing_scene_p3d_root(context.scene, fp)
            if existing_root is not None:
                skipped_existing.append(f"{os.path.basename(fp)} -> already imported as {existing_root.name}")
                continue
            if not fp or not os.path.isfile(fp):
                failed.append(f"{it.path} -> file not found")
                continue

            pre_obj_ptrs = {o.as_pointer() for o in bpy.data.objects}
            pre_col_ptrs = {c.as_pointer() for c in bpy.data.collections}
            with _suppress_a3ob_import_tracking():
                res, op_id, err = _call_first_available(
                    _A3OB_IMPORT_CANDIDATES,
                    filepath=fp,
                    load_textures=False,
                )
            if op_id:
                used_op = op_id
            if res is None:
                failed.append(f"{fp} -> {_fmt_exc(err) if err else 'unknown error'}")
            else:
                imported += 1
                imported_objs = [o for o in bpy.data.objects if o.as_pointer() not in pre_obj_ptrs]
                _tag_import_source_on_imported_data(
                    context=context,
                    filepath=fp,
                    imported_objs=imported_objs,
                    pre_collection_ptrs=pre_col_ptrs,
                )
                stats = _postprocess_imported_material_previews(
                    context,
                    imported_objs,
                    show_materials=st.import_show_materials,
                    keep_converted_textures=st.import_keep_converted_textures,
                )
                _log_import_preview_summary(fp, stats)

        if st.disable_collections_after_import:
            _disable_all_collections_in_view_layer(context, st.disable_mode)

        if skipped_existing:
            print("=== Batch Import: Skipped already imported ===")
            for item in skipped_existing:
                print(item)

        if failed:
            print("=== Batch Import: Failures ===")
            for f in failed:
                print(f)
            msg = f"Imported {imported}, skipped existing {len(skipped_existing)}, failed {len(failed)}"
            self.report({"WARNING"}, msg + " (see System Console)")
        else:
            msg = f"Imported {imported} file(s), skipped existing {len(skipped_existing)}"
            self.report({"INFO"}, msg + (f" via {used_op}" if used_op else ""))
        return {"FINISHED"}

class CRAY_OT_ModelSplitTransferSelectedToTargetCategory(Operator):
    bl_idname = "cray.model_split_transfer_to_target_category"
    bl_label = "Move/Copy Selected To Target Category"
    bl_options = {"REGISTER", "UNDO"}

    transfer_mode: EnumProperty(
        name="Action",
        items=(
            ("MOVE", "Move", "Move selected mesh objects into the target part model"),
            ("COPY", "Copy", "Copy selected mesh objects into the target part model"),
        ),
        default="MOVE",
    )

    def execute(self, context):
        st = context.scene.cray_model_split_settings
        requested_mode = str(getattr(self, "transfer_mode", "MOVE") or "MOVE").upper()
        if requested_mode != "COPY":
            requested_mode = "MOVE"

        try:
            source_root, selected, separated_from_edit = _model_split_source_and_objects_for_transfer(
                context,
                st,
                copy_selection=(requested_mode == "COPY"),
            )
            target_root = _resolve_model_split_target_part_root(context, st, source_root, force_new=False)
        except Exception as e:
            self.report({"ERROR"}, _fmt_exc(e))
            return {"CANCELLED"}

        effective_mode = requested_mode
        if separated_from_edit:
            effective_mode = "MOVE"

        if effective_mode == "MOVE":
            _prepare_moved_objects_for_named_split(selected)

        created = []
        failed = []
        copies_by_source = {}
        used_categories = set()

        for src_obj in selected:
            dup_obj = None
            try:
                category_token = _model_split_category_for_object(src_obj)
                dest_leaf = _ensure_model_split_target_category_collection(target_root, category_token)
                if dest_leaf is None:
                    failed.append(f"{src_obj.name} -> failed to create A3OB category collection")
                    continue

                if effective_mode == "COPY":
                    dup_obj = _duplicate_object_for_split(src_obj)
                    if dup_obj is None:
                        failed.append(f"{src_obj.name} -> failed to duplicate object")
                        continue
                    _set_model_split_target_lod_a3ob_props(dup_obj, category_token)
                    dest_leaf.objects.link(dup_obj)
                    copies_by_source[src_obj] = dup_obj
                    used_categories.add(_model_split_target_category_label(category_token))
                    created.append(dup_obj)
                else:
                    _move_object_to_collection(src_obj, dest_leaf, unlink_roots=source_root)
                    _set_model_split_target_lod_a3ob_props(src_obj, category_token)
                    used_categories.add(_model_split_target_category_label(category_token))
                    created.append(src_obj)
                    if not _same_id_data(source_root, target_root):
                        lingering = _direct_object_collection_names_under_root(source_root, src_obj)
                        if lingering:
                            preview = ", ".join(lingering[:5])
                            if len(lingering) > 5:
                                preview += ", ..."
                            failed.append(f"{src_obj.name} -> moved but still linked in source collection(s): {preview}")
            except Exception as e:
                failed.append(f"{src_obj.name} -> {_fmt_exc(e)}")
                if effective_mode == "COPY":
                    try:
                        if dup_obj is not None and bpy.data.objects.get(dup_obj.name) is not None and dup_obj.users == 0:
                            bpy.data.objects.remove(dup_obj)
                    except Exception:
                        pass

        if effective_mode == "COPY":
            _rewire_split_copy_object_refs(copies_by_source)

        _focus_created_split_objects(context, target_root, created)
        planner_added, planner_path = _add_model_split_part_to_planner(context, target_root)

        if failed:
            print("=== Model Split Target Category: Failures ===")
            for item in failed:
                print(item)

        if not created:
            self.report({"ERROR"}, "No mesh objects were moved or copied")
            return {"CANCELLED"}

        action_word = "Copied" if requested_mode == "COPY" else "Moved"
        if separated_from_edit and requested_mode == "MOVE":
            action_word = "Separated and moved"
        elif separated_from_edit and requested_mode == "COPY":
            action_word = "Copied selected geometry"
        category_label = ", ".join(sorted(used_categories, key=str.lower)) if used_categories else "A3OB category"
        msg = f"{action_word} {len(created)} object(s) to {target_root.name} > {category_label}"
        if planner_path:
            msg += ", added to Import/Export list" if planner_added else ", already in Import/Export list"
        if failed:
            self.report({"WARNING"}, msg + f", failed {len(failed)} (see System Console)")
        else:
            self.report({"INFO"}, msg)
        return {"FINISHED"}


def _model_split_grid_active_mesh_object(context):
    active_objects = getattr(getattr(context, "view_layer", None), "objects", None)
    active_obj = getattr(active_objects, "active", None) if active_objects is not None else None
    if active_obj is not None and getattr(active_obj, "type", None) == "MESH":
        return active_obj
    return None


def _model_split_grid_is_cutter(obj) -> bool:
    if obj is None:
        return False
    try:
        return bool(obj.get("nh_grid_cutter", False))
    except Exception:
        return False


def _model_split_grid_is_guide(obj) -> bool:
    if obj is None:
        return False
    try:
        return bool(obj.get("nh_grid_guide", False))
    except Exception:
        return False


def _model_split_grid_is_split_helper(obj) -> bool:
    return _model_split_grid_is_cutter(obj) or _model_split_grid_is_guide(obj)


def _model_split_grid_is_enabled_cutter(obj) -> bool:
    if not (_model_split_grid_is_cutter(obj) or _model_split_grid_is_guide(obj)):
        return False
    try:
        return bool(obj.get("nh_grid_enabled", True))
    except Exception:
        return True


def _model_split_grid_object_visible(context, obj) -> bool:
    if obj is None:
        return False
    try:
        return bool(obj.visible_get(view_layer=context.view_layer))
    except TypeError:
        try:
            return bool(obj.visible_get())
        except Exception:
            pass
    except Exception:
        pass
    try:
        if obj.hide_get():
            return False
    except Exception:
        pass
    try:
        if bool(getattr(obj, "hide_viewport", False)):
            return False
    except Exception:
        pass
    return True




def _model_split_grid_source_display_name(context, settings) -> str:
    source_obj = getattr(settings, "grid_source_object", None)
    if source_obj is not None:
        return _strip_blender_numeric_suffix(getattr(source_obj, "name", "") or "Source")
    source_root = getattr(settings, "grid_source_root_collection", None)
    if source_root is not None:
        return _strip_blender_numeric_suffix(getattr(source_root, "name", "") or "Source")
    active_obj = _model_split_grid_active_mesh_object(context)
    if active_obj is not None and not _model_split_grid_is_split_helper(active_obj):
        return _strip_blender_numeric_suffix(getattr(active_obj, "name", "") or "Source")
    roots = _model_split_selected_p3d_root_collections(context)
    if roots:
        return _strip_blender_numeric_suffix(getattr(roots[0], "name", "") or "Source")
    return "Scene"


def _model_split_grid_safe_name(value: str, fallback: str = "split") -> str:
    name = _strip_blender_numeric_suffix((value or "").strip())
    if name.lower().endswith(".p3d"):
        name = os.path.splitext(name)[0]
    name = _INVALID_FILENAME_CHARS_RE.sub("_", name)
    name = re.sub(r"\s+", " ", name).strip(" .")
    return name or fallback


def _model_split_grid_output_prefix(settings, source_name: str = "") -> str:
    raw = (getattr(settings, "grid_output_prefix", "") or "").strip()
    source_prefix = _model_split_grid_safe_name(source_name or "split", fallback="split")
    if not raw or raw.lower() == "split":
        raw = source_prefix
    return _model_split_grid_safe_name(
        raw,
        fallback="split",
    )


def _model_split_grid_collection_parent(context, source_root=None):
    scene_root = getattr(getattr(context, "scene", None), "collection", None)
    if scene_root is None:
        return source_root
    if source_root is not None:
        parent = _find_parent_collection(scene_root, source_root)
        if parent is not None:
            return parent
    return scene_root


def _model_split_grid_cutter_collection(context, settings, *, create: bool = False):
    collection = getattr(settings, "grid_cutter_collection", None)
    if collection is not None:
        return collection
    if not create:
        return None

    source_name = _model_split_grid_source_display_name(context, settings)
    collection_name = f"NH Grid Cut Lines - {source_name}"
    collection = bpy.data.collections.get(collection_name)
    if collection is None:
        collection = bpy.data.collections.new(collection_name)

    scene_root = getattr(getattr(context, "scene", None), "collection", None)
    if scene_root is not None:
        try:
            if _find_parent_collection(scene_root, collection) is None and scene_root != collection:
                scene_root.children.link(collection)
        except Exception:
            pass

    try:
        settings.grid_cutter_collection = collection
    except Exception:
        pass
    return collection



def _model_split_grid_delete_tagged_cutters(collection):
    if collection is None:
        return 0
    removed = 0
    for obj in list(_collect_collection_objects_recursive(collection)):
        if not _model_split_grid_is_split_helper(obj):
            continue
        try:
            bpy.data.objects.remove(obj, do_unlink=True)
            removed += 1
        except Exception as e:
            print(f"[NH Plugin] Line Grid Split: failed to remove helper {getattr(obj, 'name', '<object>')}: {_fmt_exc(e)}")
    return removed


def _model_split_grid_world_bounds_for_objects(objects):
    points = []
    for obj in objects or ():
        if obj is None or getattr(obj, "type", None) != "MESH":
            continue
        try:
            matrix = obj.matrix_world.copy()
            bound_box = list(getattr(obj, "bound_box", []) or [])
        except Exception:
            bound_box = []
        if bound_box:
            points.extend(matrix @ Vector(corner) for corner in bound_box)
            continue
        data = getattr(obj, "data", None)
        if data is None:
            continue
        for vertex in getattr(data, "vertices", []) or []:
            try:
                points.append(matrix @ vertex.co)
            except Exception:
                pass
    if not points:
        return None

    min_v = Vector((
        min(p.x for p in points),
        min(p.y for p in points),
        min(p.z for p in points),
    ))
    max_v = Vector((
        max(p.x for p in points),
        max(p.y for p in points),
        max(p.z for p in points),
    ))
    return min_v, max_v






def _model_split_grid_create_cube_mesh(name: str):
    mesh = bpy.data.meshes.new(name)
    verts = (
        (-0.5, -0.5, -0.5),
        (0.5, -0.5, -0.5),
        (0.5, 0.5, -0.5),
        (-0.5, 0.5, -0.5),
        (-0.5, -0.5, 0.5),
        (0.5, -0.5, 0.5),
        (0.5, 0.5, 0.5),
        (-0.5, 0.5, 0.5),
    )
    faces = (
        (0, 1, 2, 3),
        (4, 7, 6, 5),
        (0, 4, 5, 1),
        (1, 5, 6, 2),
        (2, 6, 7, 3),
        (3, 7, 4, 0),
    )
    mesh.from_pydata(verts, (), faces)
    mesh.update()
    return mesh


def _model_split_grid_config_values(settings):
    count_x = max(1, int(getattr(settings, "grid_count_x", 1) or 1))
    count_y = max(1, int(getattr(settings, "grid_count_y", 1) or 1))
    return count_x, count_y


def _model_split_grid_expanded_bounds(bounds, min_span: float = 0.01):
    if not bounds:
        return None
    min_v = bounds[0].copy()
    max_v = bounds[1].copy()
    for axis in range(3):
        span = float(max_v[axis] - min_v[axis])
        if abs(span) >= min_span:
            continue
        center = (float(min_v[axis]) + float(max_v[axis])) * 0.5
        half = min_span * 0.5
        min_v[axis] = center - half
        max_v[axis] = center + half
    return min_v, max_v


def _model_split_grid_auto_cut_positions(min_value: float, max_value: float, count: int):
    count = max(1, int(count or 1))
    if count <= 1:
        return []
    span = float(max_value) - float(min_value)
    if abs(span) <= 1.0e-9:
        return []
    step = span / float(count)
    return [float(min_value) + step * i for i in range(1, count)]


def _model_split_grid_unique_cut_positions(values, min_value: float, max_value: float):
    span = abs(float(max_value) - float(min_value))
    epsilon = max(span * 1.0e-5, 1.0e-5)
    result = []
    for value in sorted(float(v) for v in values):
        if value <= min_value + epsilon or value >= max_value - epsilon:
            continue
        if result and abs(value - result[-1]) <= epsilon:
            continue
        result.append(value)
    return result


def _model_split_grid_collect_guides(context, settings):
    collection = _model_split_grid_cutter_collection(context, settings, create=False)
    if collection is None:
        return []

    guides = []
    for obj in _collect_collection_objects_recursive(collection):
        if not _model_split_grid_is_guide(obj):
            continue
        if not _model_split_grid_is_enabled_cutter(obj):
            continue
        if bool(getattr(settings, "grid_use_visible_cutters_only", True)) and not _model_split_grid_object_visible(context, obj):
            continue
        guides.append(obj)
    guides.sort(key=lambda obj: (str(obj.get("nh_grid_axis", "") or ""), getattr(obj, "name", "")))
    return guides


def _model_split_grid_guide_cut_positions(context, settings, bounds):
    positions = {"X": [], "Y": []}
    for guide in _model_split_grid_collect_guides(context, settings):
        try:
            axis = str(guide.get("nh_grid_axis", "") or "").strip().upper()
        except Exception:
            axis = ""
        if axis not in positions:
            continue
        try:
            loc = guide.matrix_world.translation
        except Exception:
            continue
        positions[axis].append(float(loc.x if axis == "X" else loc.y))

    min_v, max_v = bounds
    positions["X"] = _model_split_grid_unique_cut_positions(positions["X"], min_v.x, max_v.x)
    positions["Y"] = _model_split_grid_unique_cut_positions(positions["Y"], min_v.y, max_v.y)
    return positions


def _model_split_grid_cut_edges(context, settings, source_objects):
    bounds = _model_split_grid_expanded_bounds(_model_split_grid_world_bounds_for_objects(source_objects))
    if bounds is None:
        raise RuntimeError("Could not calculate source bounds for line grid split")
    min_v, max_v = bounds
    count_x = max(1, int(getattr(settings, "grid_count_x", 1) or 1))
    count_y = max(1, int(getattr(settings, "grid_count_y", 1) or 1))

    guide_positions = _model_split_grid_guide_cut_positions(context, settings, bounds)
    x_cuts = guide_positions["X"] or _model_split_grid_auto_cut_positions(min_v.x, max_v.x, count_x)
    y_cuts = guide_positions["Y"] or _model_split_grid_auto_cut_positions(min_v.y, max_v.y, count_y)
    x_cuts = _model_split_grid_unique_cut_positions(x_cuts, min_v.x, max_v.x)
    y_cuts = _model_split_grid_unique_cut_positions(y_cuts, min_v.y, max_v.y)

    x_edges = [float(min_v.x), *x_cuts, float(max_v.x)]
    y_edges = [float(min_v.y), *y_cuts, float(max_v.y)]
    used_guides = bool(guide_positions["X"] or guide_positions["Y"])
    return bounds, x_edges, y_edges, used_guides


def _model_split_grid_iter_cells(x_edges, y_edges):
    part_number = 1
    # Number top-to-bottom in top view, then left-to-right in each row.
    for iy in range(len(y_edges) - 2, -1, -1):
        for ix in range(len(x_edges) - 1):
            yield (
                part_number,
                ix,
                iy,
                float(x_edges[ix]),
                float(x_edges[ix + 1]),
                float(y_edges[iy]),
                float(y_edges[iy + 1]),
            )
            part_number += 1


def _model_split_grid_create_temp_collection(context, name: str):
    collection = bpy.data.collections.new(name)
    scene_root = getattr(getattr(context, "scene", None), "collection", None)
    if scene_root is not None:
        scene_root.children.link(collection)
    return collection


def _model_split_grid_remove_temp_collection(collection):
    if collection is None:
        return
    for obj in list(_collect_collection_objects_recursive(collection)):
        _model_split_grid_remove_object(obj)
    _model_split_grid_remove_collection_tree(collection)


def _model_split_grid_create_cell_cutter(context, temp_collection, name: str, bounds, x0: float, x1: float, y0: float, y1: float):
    min_v, max_v = bounds
    span_z = max(float(max_v.z - min_v.z), 0.01)
    pad_z = max(span_z * 0.05, 0.01)
    size_x = max(float(x1 - x0), 0.001)
    size_y = max(float(y1 - y0), 0.001)
    size_z = span_z + pad_z * 2.0

    mesh = _model_split_grid_create_cube_mesh(name)
    obj = bpy.data.objects.new(name, mesh)
    obj.location = (
        (float(x0) + float(x1)) * 0.5,
        (float(y0) + float(y1)) * 0.5,
        (float(min_v.z) + float(max_v.z)) * 0.5,
    )
    obj.scale = (size_x, size_y, size_z)
    obj["nh_grid_temp_cell_cutter"] = True
    try:
        obj.display_type = "WIRE"
    except Exception:
        pass
    _link_object_to_collection(obj, temp_collection)
    _ensure_collection_visible_in_view_layer(context, temp_collection)
    try:
        context.view_layer.update()
    except Exception:
        pass
    return obj


def _model_split_grid_create_guide_object(context, collection, axis: str, index: int, position: float, bounds):
    axis = (axis or "X").upper()
    min_v, max_v = bounds
    span_x = max(float(max_v.x - min_v.x), 0.01)
    span_y = max(float(max_v.y - min_v.y), 0.01)
    span_z = max(float(max_v.z - min_v.z), 0.01)
    thickness = max(min(span_x, span_y) * 0.006, 0.02)
    pad_xy = max(max(span_x, span_y) * 0.02, 0.05)
    pad_z = max(span_z * 0.05, 0.05)

    name = f"CUT_{axis}{index:02d}"
    mesh = _model_split_grid_create_cube_mesh(name)
    obj = bpy.data.objects.new(name, mesh)
    if axis == "X":
        obj.location = (float(position), (min_v.y + max_v.y) * 0.5, (min_v.z + max_v.z) * 0.5)
        obj.scale = (thickness, span_y + pad_xy * 2.0, span_z + pad_z * 2.0)
    else:
        obj.location = ((min_v.x + max_v.x) * 0.5, float(position), (min_v.z + max_v.z) * 0.5)
        obj.scale = (span_x + pad_xy * 2.0, thickness, span_z + pad_z * 2.0)

    obj["nh_grid_guide"] = True
    obj["nh_grid_axis"] = axis
    obj["nh_grid_index"] = int(index)
    obj["nh_grid_enabled"] = True
    try:
        obj.display_type = "WIRE"
        obj.show_name = True
        obj.color = (0.0, 0.85, 1.0, 0.45) if axis == "X" else (1.0, 0.65, 0.0, 0.45)
    except Exception:
        pass
    _link_object_to_collection(obj, collection)
    _ensure_collection_visible_in_view_layer(context, collection)
    return obj


def _model_split_grid_category_for_object(obj) -> str:
    category = _model_split_category_for_object(obj)
    if obj is not None and hasattr(obj, "a3ob_properties_object"):
        try:
            if bool(getattr(obj.a3ob_properties_object, "is_a3_lod", False)):
                return category
        except Exception:
            pass

    text_parts = [getattr(obj, "name", "") or ""]
    for col in getattr(obj, "users_collection", []) or []:
        text_parts.append(getattr(col, "name", "") or "")
    text = " ".join(_logical_collection_name(part) for part in text_parts)
    if "roadway" in text:
        return "ROADWAY"
    if "memory" in text or "point cloud" in text or "pointcloud" in text:
        return "POINT_CLOUDS"
    if (
        "geometry" in text or
        "shadow" in text or
        "physx" in text or
        "view geometry" in text or
        "fire geometry" in text
    ):
        return "GEOMETRIES"
    if "resolution" in text or "visual" in text:
        return "RESOLUTION"
    return category


def _model_split_grid_copy_a3ob_object_props(src_obj, dst_obj):
    if src_obj is None or dst_obj is None:
        return False
    if not hasattr(src_obj, "a3ob_properties_object") or not hasattr(dst_obj, "a3ob_properties_object"):
        return False
    try:
        src_props = src_obj.a3ob_properties_object
        dst_props = dst_obj.a3ob_properties_object
        for prop in getattr(src_props, "bl_rna", ()).properties:
            identifier = getattr(prop, "identifier", "")
            if not identifier or identifier == "rna_type" or getattr(prop, "is_readonly", False):
                continue
            try:
                setattr(dst_props, identifier, getattr(src_props, identifier))
            except Exception:
                pass
        return True
    except Exception:
        return False


def _model_split_grid_set_piece_names(obj, piece_name: str):
    if obj is None:
        return
    try:
        obj.name = piece_name
    except Exception:
        pass
    try:
        if obj.data is not None:
            obj.data.name = piece_name
    except Exception:
        pass


def _model_split_grid_prepare_piece_props(src_obj, dst_obj, category_token: str, piece_name: str):
    copied = _model_split_grid_copy_a3ob_object_props(src_obj, dst_obj)
    if not copied:
        _set_model_split_target_lod_a3ob_props(dst_obj, category_token)
    _model_split_grid_set_piece_names(dst_obj, piece_name)


def _model_split_grid_has_faces(obj) -> bool:
    data = getattr(obj, "data", None)
    if data is None:
        return False
    try:
        return len(data.polygons) > 0
    except Exception:
        return False


def _model_split_grid_should_clip_as_points(obj, category_token: str) -> bool:
    return category_token == "POINT_CLOUDS" or not _model_split_grid_has_faces(obj)


def _model_split_grid_is_proxy_object(obj) -> bool:
    if obj is None or getattr(obj, "type", None) != "MESH":
        return False
    try:
        if _is_a3ob_proxy_object(obj):
            return True
    except Exception:
        pass
    if hasattr(obj, "a3ob_properties_object_proxy"):
        try:
            props = obj.a3ob_properties_object_proxy
            if bool(getattr(props, "is_a3_proxy", False)):
                return True
        except Exception:
            pass
    name = (getattr(obj, "name", "") or "").strip().lower()
    return name.startswith("proxy:")


def _model_split_grid_output_container(context, source_root, prefix: str):
    parent = _model_split_grid_collection_parent(context, source_root)
    if parent is None:
        return None
    container_name = f"NH Grid Split - {prefix}"
    container = bpy.data.collections.new(container_name)
    parent.children.link(container)
    try:
        container.color_tag = "COLOR_04"
    except Exception:
        pass
    return container


def _model_split_grid_output_root_name(prefix: str, grid_id: str) -> str:
    root_name = f"{prefix}_{grid_id}.p3d"
    root_name = _INVALID_FILENAME_CHARS_RE.sub("_", root_name)
    return root_name


def _model_split_grid_create_output_root(context, container, source_root, root_name: str):
    if container is None:
        return None
    target_root = bpy.data.collections.new(root_name)
    container.children.link(target_root)
    try:
        if source_root is not None and getattr(source_root, "color_tag", None):
            target_root.color_tag = source_root.color_tag
    except Exception:
        pass
    if source_root is not None:
        _set_ie_source_path_tag(target_root, _derive_split_export_source_path(source_root, root_name))
    return target_root


def _model_split_grid_remove_collection_tree(collection):
    if collection is None:
        return
    for child in list(getattr(collection, "children", []) or []):
        _model_split_grid_remove_collection_tree(child)
    for obj in list(getattr(collection, "objects", []) or []):
        try:
            collection.objects.unlink(obj)
        except Exception:
            pass
    try:
        bpy.data.collections.remove(collection)
    except Exception:
        pass


def _model_split_grid_point_inside_cutter(cutter, world_point, epsilon: float = 1.0e-6) -> bool:
    if cutter is None:
        return False
    try:
        local = cutter.matrix_world.inverted_safe() @ world_point
    except Exception:
        return False

    bound_box = list(getattr(cutter, "bound_box", []) or [])
    if not bound_box and getattr(cutter, "data", None) is not None:
        try:
            bound_box = [vertex.co[:] for vertex in cutter.data.vertices]
        except Exception:
            bound_box = []
    if not bound_box:
        bound_box = [(-0.5, -0.5, -0.5), (0.5, 0.5, 0.5)]

    min_v = Vector((
        min(Vector(corner).x for corner in bound_box),
        min(Vector(corner).y for corner in bound_box),
        min(Vector(corner).z for corner in bound_box),
    ))
    max_v = Vector((
        max(Vector(corner).x for corner in bound_box),
        max(Vector(corner).y for corner in bound_box),
        max(Vector(corner).z for corner in bound_box),
    ))
    return (
        min_v.x - epsilon <= local.x <= max_v.x + epsilon and
        min_v.y - epsilon <= local.y <= max_v.y + epsilon and
        min_v.z - epsilon <= local.z <= max_v.z + epsilon
    )


def _model_split_grid_apply_boolean_intersect(context, obj, cutter):
    if obj is None or cutter is None:
        raise RuntimeError("Missing object or cutter for boolean split")
    modifier = None
    old_mesh = getattr(obj, "data", None)
    try:
        modifier = obj.modifiers.new("NH Grid Cutter Intersect", "BOOLEAN")
        modifier.operation = "INTERSECT"
        modifier.object = cutter
        if hasattr(modifier, "solver"):
            modifier.solver = "EXACT"
        try:
            context.view_layer.update()
        except Exception:
            pass
        depsgraph = context.evaluated_depsgraph_get()
        evaluated = obj.evaluated_get(depsgraph)
        try:
            new_mesh = bpy.data.meshes.new_from_object(
                evaluated,
                depsgraph=depsgraph,
                preserve_all_data_layers=True,
            )
        except TypeError:
            new_mesh = bpy.data.meshes.new_from_object(evaluated, depsgraph=depsgraph)
        if new_mesh is None:
            raise RuntimeError("Boolean modifier produced no mesh")
        obj.modifiers.remove(modifier)
        modifier = None
        obj.data = new_mesh
        if old_mesh is not None and getattr(old_mesh, "users", 0) == 0:
            try:
                bpy.data.meshes.remove(old_mesh)
            except Exception:
                pass
        return obj
    except Exception:
        if modifier is not None:
            try:
                obj.modifiers.remove(modifier)
            except Exception:
                pass
        raise


def _model_split_grid_cleanup_mesh(obj, *, recalc_normals: bool = False, remove_loose: bool = False):
    mesh = getattr(obj, "data", None)
    if mesh is None:
        return
    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        if remove_loose:
            loose_verts = [vert for vert in bm.verts if not vert.link_edges and not vert.link_faces]
            if loose_verts:
                bmesh.ops.delete(bm, geom=loose_verts, context="VERTS")
        if recalc_normals and bm.faces:
            bmesh.ops.recalc_face_normals(bm, faces=list(bm.faces))
        bm.to_mesh(mesh)
        mesh.update()
    finally:
        bm.free()


def _model_split_grid_piece_is_empty(obj, settings, *, point_piece: bool = False) -> bool:
    data = getattr(obj, "data", None)
    if data is None:
        return True
    try:
        vertex_count = len(data.vertices)
    except Exception:
        vertex_count = 0
    try:
        face_count = len(data.polygons)
    except Exception:
        face_count = 0
    if vertex_count <= 0:
        return True
    min_vertices = max(0, int(getattr(settings, "grid_min_vertices", 0) or 0))
    min_faces = max(0, int(getattr(settings, "grid_min_faces", 0) or 0))
    if vertex_count < min_vertices:
        return True
    if not point_piece and bool(getattr(settings, "grid_skip_empty_pieces", True)) and face_count < min_faces:
        return True
    return False


def _model_split_grid_remove_object(obj):
    if obj is None:
        return
    data = getattr(obj, "data", None)
    try:
        bpy.data.objects.remove(obj, do_unlink=True)
    except Exception:
        pass
    if data is not None:
        try:
            if getattr(data, "users", 0) == 0:
                bpy.data.meshes.remove(data)
        except Exception:
            pass


def _model_split_grid_make_face_piece(context, src_obj, cutter, dest_collection, settings, piece_name, category_token):
    dup_obj = _duplicate_object_for_split(src_obj)
    if dup_obj is None:
        raise RuntimeError("Failed to duplicate source object")
    _model_split_grid_prepare_piece_props(src_obj, dup_obj, category_token, piece_name)
    _link_object_to_collection(dup_obj, dest_collection)
    _ensure_collection_visible_in_view_layer(context, dest_collection)
    try:
        _model_split_grid_apply_boolean_intersect(context, dup_obj, cutter)
        if category_token == "ROADWAY":
            _model_split_grid_cleanup_mesh(dup_obj, recalc_normals=True, remove_loose=True)
        if _model_split_grid_piece_is_empty(dup_obj, settings, point_piece=False):
            _model_split_grid_remove_object(dup_obj)
            return None
        return dup_obj
    except Exception:
        _model_split_grid_remove_object(dup_obj)
        raise


def _model_split_grid_copy_vertex_groups(src_obj, dst_obj, index_map):
    if src_obj is None or dst_obj is None or not index_map:
        return
    try:
        while dst_obj.vertex_groups:
            dst_obj.vertex_groups.remove(dst_obj.vertex_groups[0])
    except Exception:
        pass
    for src_group in getattr(src_obj, "vertex_groups", []) or []:
        try:
            dst_group = dst_obj.vertex_groups.new(name=src_group.name)
        except Exception:
            continue
        for old_index, new_index in index_map.items():
            try:
                weight = src_group.weight(old_index)
            except Exception:
                continue
            try:
                dst_group.add([new_index], weight, "ADD")
            except Exception:
                pass


def _model_split_grid_make_point_piece(src_obj, cutter, dest_collection, settings, piece_name, category_token):
    source_mesh = getattr(src_obj, "data", None)
    if source_mesh is None:
        return None

    verts = []
    index_map = {}
    source_matrix = src_obj.matrix_world.copy()
    for vertex in source_mesh.vertices:
        try:
            world_point = source_matrix @ vertex.co
        except Exception:
            continue
        if not _model_split_grid_point_inside_cutter(cutter, world_point):
            continue
        index_map[int(vertex.index)] = len(verts)
        verts.append(tuple(vertex.co))

    if not verts:
        return None

    edges = []
    for edge in getattr(source_mesh, "edges", []) or []:
        try:
            v0, v1 = int(edge.vertices[0]), int(edge.vertices[1])
        except Exception:
            continue
        if v0 in index_map and v1 in index_map:
            edges.append((index_map[v0], index_map[v1]))

    mesh = bpy.data.meshes.new(piece_name)
    mesh.from_pydata(verts, edges, ())
    try:
        for material in getattr(source_mesh, "materials", []) or []:
            mesh.materials.append(material)
    except Exception:
        pass
    mesh.update()

    dup_obj = src_obj.copy()
    dup_obj.data = mesh
    try:
        dup_obj.parent = None
    except Exception:
        pass
    try:
        dup_obj.matrix_world = src_obj.matrix_world.copy()
    except Exception:
        pass
    try:
        for modifier in list(getattr(dup_obj, "modifiers", []) or []):
            dup_obj.modifiers.remove(modifier)
    except Exception:
        pass
    _clear_ie_source_path_tag(dup_obj)
    _model_split_grid_prepare_piece_props(src_obj, dup_obj, category_token, piece_name)
    _model_split_grid_copy_vertex_groups(src_obj, dup_obj, index_map)
    _link_object_to_collection(dup_obj, dest_collection)

    if _model_split_grid_piece_is_empty(dup_obj, settings, point_piece=True):
        _model_split_grid_remove_object(dup_obj)
        return None
    return dup_obj


def _model_split_grid_make_proxy_piece(src_obj, cutter, dest_collection, settings, piece_name, category_token):
    try:
        origin = src_obj.matrix_world.translation.copy()
    except Exception:
        return None

    if not _model_split_grid_point_inside_cutter(cutter, origin):
        return None

    dup_obj = _duplicate_object_for_split(src_obj)
    if dup_obj is None:
        raise RuntimeError("Failed to duplicate proxy object")

    try:
        for modifier in list(getattr(dup_obj, "modifiers", []) or []):
            dup_obj.modifiers.remove(modifier)
    except Exception:
        pass

    _model_split_grid_prepare_piece_props(src_obj, dup_obj, category_token, piece_name)
    _link_object_to_collection(dup_obj, dest_collection)
    return dup_obj


def _model_split_grid_resolve_source(context, settings):
    source_obj = getattr(settings, "grid_source_object", None)
    source_root = getattr(settings, "grid_source_root_collection", None)
    if source_obj is not None:
        if getattr(source_obj, "type", None) != "MESH":
            raise RuntimeError("Source Object must be a mesh")
        resolved_root = _find_p3d_root_collection_for_collection(context, source_root, require_p3d=False) if source_root is not None else None
        if resolved_root is None:
            resolved_root = _find_p3d_root_collection_for_object(context, source_obj)
        return resolved_root, [source_obj]

    if source_root is not None:
        resolved_root = _find_p3d_root_collection_for_collection(context, source_root, require_p3d=False) or source_root
        source_objects = [
            obj for obj in _collect_collection_objects_recursive(resolved_root)
            if getattr(obj, "type", None) == "MESH" and not _model_split_grid_is_split_helper(obj)
        ]
        if not source_objects:
            raise RuntimeError(f"Source Root Collection '{resolved_root.name}' contains no mesh objects")
        return resolved_root, source_objects

    selected_roots = _model_split_selected_p3d_root_collections(context)
    if len(selected_roots) == 1:
        root = selected_roots[0]
        source_objects = [
            obj for obj in _collect_collection_objects_recursive(root)
            if getattr(obj, "type", None) == "MESH" and not _model_split_grid_is_split_helper(obj)
        ]
        if source_objects:
            return root, source_objects

    active_obj = _model_split_grid_active_mesh_object(context)
    if active_obj is not None and not _model_split_grid_is_split_helper(active_obj):
        return _find_p3d_root_collection_for_object(context, active_obj), [active_obj]

    selected_meshes = [
        obj for obj in getattr(context, "selected_objects", []) or []
        if getattr(obj, "type", None) == "MESH" and not _model_split_grid_is_split_helper(obj)
    ]
    if selected_meshes:
        return _find_p3d_root_collection_for_object(context, selected_meshes[0]), selected_meshes

    raise RuntimeError("Choose Source Object, Source Root Collection, an active mesh, or one selected .p3d root collection")


def _model_split_grid_hide_sources(source_objects):
    for obj in source_objects or ():
        try:
            obj.hide_set(True)
        except Exception:
            pass
        try:
            obj.hide_viewport = True
        except Exception:
            pass
        try:
            obj.hide_render = True
        except Exception:
            pass


def _model_split_grid_hide_cutters(cutter_collection, cutters):
    if cutter_collection is not None:
        try:
            cutter_collection.hide_viewport = True
        except Exception:
            pass
    for cutter in cutters or ():
        try:
            cutter.hide_set(True)
        except Exception:
            pass
        try:
            cutter.hide_viewport = True
        except Exception:
            pass


class CRAY_OT_ModelSplitGridCreateCutters(Operator):
    bl_idname = "cray.model_split_grid_create_cutters"
    bl_label = "Create/Edit Cut Lines"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.cray_model_split_settings
        try:
            source_root, source_objects = _model_split_grid_resolve_source(context, settings)
            bounds = _model_split_grid_expanded_bounds(_model_split_grid_world_bounds_for_objects(source_objects))
            if bounds is None:
                raise RuntimeError("Could not calculate source bounds for cut lines")

            count_x, count_y = _model_split_grid_config_values(settings)
            guide_collection = _model_split_grid_cutter_collection(context, settings, create=True)
            if guide_collection is None:
                raise RuntimeError("Could not create cut lines collection")

            removed = _model_split_grid_delete_tagged_cutters(guide_collection)
            created = []
            min_v, max_v = bounds
            for idx, position in enumerate(_model_split_grid_auto_cut_positions(min_v.x, max_v.x, count_x), start=1):
                created.append(_model_split_grid_create_guide_object(context, guide_collection, "X", idx, position, bounds))
            for idx, position in enumerate(_model_split_grid_auto_cut_positions(min_v.y, max_v.y, count_y), start=1):
                created.append(_model_split_grid_create_guide_object(context, guide_collection, "Y", idx, position, bounds))

            _ensure_collection_visible_in_view_layer(context, guide_collection)
            _deselect_all_in_view_layer(context)
            for obj in created:
                try:
                    obj.select_set(True)
                except Exception:
                    pass
            if created:
                try:
                    context.view_layer.objects.active = created[0]
                except Exception:
                    pass

            root_name = getattr(source_root, "name", "") if source_root is not None else _model_split_grid_source_display_name(context, settings)
            self.report({"INFO"}, f"Created {len(created)} cut line(s) for {count_x}x{count_y} split on {root_name}, removed {removed} old helper(s)")
            return {"FINISHED"}
        except Exception as e:
            self.report({"ERROR"}, _fmt_exc(e))
            return {"CANCELLED"}


class CRAY_OT_ModelSplitGridSelectCutters(Operator):
    bl_idname = "cray.model_split_grid_select_cutters"
    bl_label = "Select Cut Lines"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.cray_model_split_settings
        guide_collection = _model_split_grid_cutter_collection(context, settings, create=False)
        if guide_collection is None:
            self.report({"ERROR"}, "Create cut lines first")
            return {"CANCELLED"}

        guides = [
            obj for obj in _collect_collection_objects_recursive(guide_collection)
            if getattr(obj, "type", None) == "MESH" and _model_split_grid_is_guide(obj)
        ]
        _ensure_collection_visible_in_view_layer(context, guide_collection)
        _deselect_all_in_view_layer(context)
        for obj in guides:
            try:
                obj.hide_set(False)
            except Exception:
                pass
            try:
                obj.hide_viewport = False
            except Exception:
                pass
            try:
                obj.select_set(True)
            except Exception:
                pass
        if guides:
            try:
                context.view_layer.objects.active = guides[0]
            except Exception:
                pass
        self.report({"INFO"}, f"Selected {len(guides)} cut line(s)")
        return {"FINISHED"}


class CRAY_OT_ModelSplitGridClearCutters(Operator):
    bl_idname = "cray.model_split_grid_clear_cutters"
    bl_label = "Clear Cut Lines"
